SELECT a.id, a.title, a.summary, a.cover_image, a.views, a.likes, a.favorites, a.comments_count, a.is_top, a.is_recommend, a.status, a.published_time, a.create_time, u.username AS author_name, u.avatar AS author_avatar, c.name AS category_name FROM articles a LEFT JOIN users u ON a.create_by = u.id LEFT JOIN categories c ON a.category_id = c.id WHERE a.deleted = 0
AND a.status = #{status}
AND a.category_id = #{categoryId}
AND ( a.title ILIKE CONCAT('%', #{keyword}, '%') OR a.summary ILIKE CONCAT('%', #{keyword}, '%') OR a.content ILIKE CONCAT('%', #{keyword}, '%') )
GROUP BY a.id, u.username, u.avatar, c.name ORDER BY a.is_top DESC, a.create_time DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(DISTINCT a.id) FROM articles a LEFT JOIN users u ON a.create_by = u.id LEFT JOIN categories c ON a.category_id = c.id LEFT JOIN article_tags at ON a.id = at.article_id LEFT JOIN tags t ON at.tag_id = t.id WHERE a.deleted = 0
AND a.status = #{status}
AND a.category_id = #{categoryId}
AND ( a.title ILIKE CONCAT('%', #{keyword}, '%') OR a.summary ILIKE CONCAT('%', #{keyword}, '%') OR a.content ILIKE CONCAT('%', #{keyword}, '%') )

SELECT a.id, a.title, a.summary, a.cover_image, a.views, a.likes, a.favorites, a.comments_count, a.is_top, a.is_recommend, a.status, a.published_time, a.create_time, u.username AS author_name, u.avatar AS author_avatar, c.name AS category_name FROM articles a LEFT JOIN users u ON a.create_by = u.id LEFT JOIN categories c ON a.category_id = c.id WHERE a.deleted = 0 AND a.status = 1
AND (a.title ILIKE CONCAT('%', #{keyword}, '%') OR a.summary ILIKE CONCAT('%', #{keyword}, '%') OR a.content ILIKE CONCAT('%', #{keyword}, '%') )
AND a.category_id = #{categoryId}
AND a.id IN ( SELECT DISTINCT at2.article_id FROM article_tags at2 WHERE at2.deleted = 0 AND at2.tag_id IN
#{tagId}
)
GROUP BY a.id, u.username, u.avatar, c.name ORDER BY a.is_top DESC, a.published_time DESC, a.create_time DESC LIMIT #{pageSize} OFFSET #{offset}
